// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes memory data) public {
        Reverter r = new Reverter();
        bool ok = true;
        try c.forward(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: forward to a reverting callee must revert.
        assertTrue(ok == false, "forward must revert when callee reverts");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
